previewCss:
.darma-loader-soccer-roll {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
  background-color: #eef2ff;
  background-image:
    radial-gradient(circle at 50% 50%, var(--loader-color, #6366f1) 18%, transparent 19%),
    radial-gradient(circle at 20% 30%, var(--loader-color, #6366f1) 8%, transparent 9%),
    radial-gradient(circle at 80% 30%, var(--loader-color, #6366f1) 8%, transparent 9%),
    radial-gradient(circle at 25% 80%, var(--loader-color, #6366f1) 8%, transparent 9%),
    radial-gradient(circle at 75% 80%, var(--loader-color, #6366f1) 8%, transparent 9%);
  animation: darma-loader-soccer-roll-spin 1s linear infinite;
}
@keyframes darma-loader-soccer-roll-spin { to { transform: rotate(360deg); } }

